import sys
sys.path.insert(0, '.')
from durationkit.parse import parse_duration

# Additional edge cases
def test(text, expected):
    try:
        res = parse_duration(text)
    except Exception as e:
        print(f'FAIL: {text!r} raised {type(e).__name__}: {e}')
        sys.exit(1)
    if abs(res - expected) > 1e-12:
        print(f'FAIL: {text!r} -> {res}, expected {expected}')
        sys.exit(1)
    else:
        print(f'OK: {text!r} -> {res}')

# Zero variations
test('0', 0.0)
test('0s', 0.0)
test('0ms', 0.0)
test('0h', 0.0)
test('0d', 0.0)
test('0d0h0m0s0ms', 0.0)

# Mixed whitespace
test('  2d   3h 4m 5s 6ms  ', 2*86400 + 3*3600 + 4*60 + 5 + 6*0.001)

# Ensure no whitespace between number and unit
error_cases = ['1 h', '2h 3m', '4m 5s', '1s 2ms']
for case in error_cases:
    try:
        parse_duration(case)
        print(f'FAIL: {case!r} did not raise')
        sys.exit(1)
    except ValueError:
        print(f'OK: {case!r} raised ValueError')
    except Exception as e:
